"use client";

import React, { useId, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";

import { cn } from "@/lib/utils";

export type TooltipSide = "top" | "right" | "bottom" | "left";

type TriggerProps = React.HTMLAttributes<HTMLElement> & {
  ref?: React.Ref<HTMLElement>;
};

export function Tooltip({
  children,
  content,
  side = "top",
  delayDuration = 400,
  className,
}: {
  children: React.ReactElement<TriggerProps>;
  content: React.ReactNode;
  side?: TooltipSide;
  delayDuration?: number;
  className?: string;
}) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const [point, setPoint] = useState<{ top: number; left: number } | null>(
    null,
  );
  const rootRef = useRef<HTMLSpanElement>(null);
  const tipRef = useRef<HTMLSpanElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  function clearTimer() {
    if (timer.current) {
      clearTimeout(timer.current);
      timer.current = null;
    }
  }

  function show(immediate: boolean) {
    clearTimer();

    if (immediate || delayDuration <= 0) {
      setOpen(true);
      return;
    }

    timer.current = setTimeout(() => setOpen(true), delayDuration);
  }

  function hide(nextFocus: EventTarget | null) {
    clearTimer();

    if (nextFocus instanceof Node && rootRef.current?.contains(nextFocus)) {
      return;
    }

    setOpen(false);
  }

  useLayoutEffect(() => {
    if (!open || !rootRef.current || !tipRef.current) {
      return;
    }

    const trigger = rootRef.current.getBoundingClientRect();
    const tip = tipRef.current.getBoundingClientRect();
    const gap = 8;
    let nextSide = side;

    if (
      side === "top" &&
      trigger.top - tip.height - gap < 8 &&
      window.innerHeight - trigger.bottom > trigger.top
    ) {
      nextSide = "bottom";
    } else if (
      side === "bottom" &&
      trigger.bottom + tip.height + gap > window.innerHeight - 8 &&
      trigger.top > window.innerHeight - trigger.bottom
    ) {
      nextSide = "top";
    } else if (
      side === "left" &&
      trigger.left - tip.width - gap < 8 &&
      window.innerWidth - trigger.right > trigger.left
    ) {
      nextSide = "right";
    } else if (
      side === "right" &&
      trigger.right + tip.width + gap > window.innerWidth - 8 &&
      trigger.left > window.innerWidth - trigger.right
    ) {
      nextSide = "left";
    }

    let top = trigger.top - tip.height - gap;
    let left = trigger.left + trigger.width / 2 - tip.width / 2;

    if (nextSide === "bottom") {
      top = trigger.bottom + gap;
    }

    if (nextSide === "left") {
      top = trigger.top + trigger.height / 2 - tip.height / 2;
      left = trigger.left - tip.width - gap;
    }

    if (nextSide === "right") {
      top = trigger.top + trigger.height / 2 - tip.height / 2;
      left = trigger.right + gap;
    }

    left = Math.min(Math.max(8, left), window.innerWidth - tip.width - 8);
    top = Math.min(Math.max(8, top), window.innerHeight - tip.height - 8);
    setPoint({ top, left });
  }, [open, side, content]);

  const child = React.cloneElement(children, {
    "aria-describedby": open ? id : undefined,
    onKeyDown: (event: React.KeyboardEvent<HTMLElement>) => {
      children.props.onKeyDown?.(event);

      if (event.key === "Escape") {
        setOpen(false);
      }
    },
  });

  return (
    <span
      ref={rootRef}
      className="inline-flex"
      onMouseEnter={() => show(false)}
      onMouseLeave={() => {
        if (rootRef.current?.contains(document.activeElement)) {
          return;
        }

        hide(null);
      }}
      onFocus={() => show(true)}
      onBlur={(event) => hide(event.relatedTarget)}
    >
      {child}
      {open
        ? createPortal(
            <span
              ref={tipRef}
              id={id}
              role="tooltip"
              data-side={side}
              style={{
                position: "fixed",
                top: point?.top ?? -9999,
                left: point?.left ?? -9999,
              }}
              className={cn(
                "bg-foreground text-background pointer-events-none z-50 max-w-xs rounded-md px-2 py-1 text-sm",
                className,
              )}
            >
              {content}
            </span>,
            document.body,
          )
        : null}
    </span>
  );
}
